    $rows += '| {0} | {1} | {2} | {3} | {4} |' -f $entry.section_number,$entry.unit_id,($entry.title -replace '\|','\|'),$entry.status,$link
}
[IO.File]::WriteAllText((Join-Path $root 'lecture-list.md'), ($rows -join "`n") + "`n", $utf8)
