param(
    [Parameter(Mandatory=$true)][string]$SessionCookie,
    [string]$OutputDirectory
)
$ErrorActionPreference='Stop'
if (!$OutputDirectory) { $OutputDirectory=Split-Path -Parent $MyInvocation.MyCommand.Path }
$root=[IO.Path]::GetFullPath($OutputDirectory)
$materialRoot=Join-Path $root 'materials'
[IO.Directory]::CreateDirectory($materialRoot) | Out-Null
$utf8=New-Object Text.UTF8Encoding $false,$true
$session=New-Object Microsoft.PowerShell.Commands.WebRequestSession
$session.Cookies.Add((New-Object Net.Cookie('connect.sid',$SessionCookie,'/','.inflearn.com')))
$headers=@{Origin='https://www.inflearn.com';Referer='https://www.inflearn.com/';'x-request-from'='inflearn-frontend'}
function Api-Json([string]$Path) {
    $r=Invoke-WebRequest -UseBasicParsing -Uri ('https://ucc-api.inflearn.com'+$Path) -WebSession $session -Headers $headers -TimeoutSec 40
    $raw=$utf8.GetString($r.RawContentStream.ToArray())
    # Windows PowerShell dictionaries cannot hold these two server keys together.
    $data=($raw -creplace '"nowUTC"\s*:', '"nowUTC_compat":') | ConvertFrom-Json
    if ($data.statusCode -ne 'OK') { throw ('API response: '+$data.statusCode) }
    return $data.data
}
function Download-File([string]$Url,[string]$Path) {
    $uri=[uri]$Url
    if ($uri.Scheme -ne 'https' -or $uri.Host -notin @('cdn.inflearn.com','cdn.inflab.com')) {throw 'Unexpected file host'}
    $r=Invoke-WebRequest -UseBasicParsing -Uri $Url -Headers @{Referer='https://www.inflearn.com/'} -TimeoutSec 60 -MaximumRedirection 0
    $bytes=$r.RawContentStream.ToArray()
    if (!$bytes.Length -or $r.Headers['Content-Type'] -like 'text/html*') {throw 'Invalid attachment response'}
    [IO.File]::WriteAllBytes($Path,$bytes)
}
$curriculum=[IO.File]::ReadAllText((Join-Path $root 'curriculum.json'),$utf8) | ConvertFrom-Json
$entries=New-Object 'System.Collections.Generic.List[object]'
$sectionNumber=0
foreach ($section in $curriculum.data.curriculum) {
    $sectionNumber++
    foreach ($unit in $section.units) {
        if (!$unit.hasAttachment -and !$unit.hasBody) {continue}
        $relative='section-{0:00}/{1}' -f $sectionNumber,$unit.id
        $folder=Join-Path $materialRoot $relative
        [IO.Directory]::CreateDirectory($folder) | Out-Null
        $entry=[ordered]@{section_number=$sectionNumber;unit_id=$unit.id;title=$unit.title;has_video=$unit.hasVideo;status='downloaded';files=@();errors=@()}
        if ($unit.hasBody) {
            try {
                $detail=Api-Json ('/client/api/v2/units/'+$unit.id)
                $body=[string]$detail.body
                if (!$body) {throw 'Expected body is empty'}
                $links=@([regex]::Matches($body,'href="([^"]+)"') | ForEach-Object {[Net.WebUtility]::HtmlDecode($_.Groups[1].Value)} | Select-Object -Unique)
                $images=@([regex]::Matches($body,'<img\b[^>]*\bsrc="([^"]+)"') | ForEach-Object {[Net.WebUtility]::HtmlDecode($_.Groups[1].Value)} | Select-Object -Unique)
                $number=0
                foreach ($image in $images) {
                    $number++
                    try {
                        $ext=[IO.Path]::GetExtension(([uri]$image).AbsolutePath)
                        if ($ext -notmatch '^\.[a-zA-Z0-9]{1,6}$') {$ext='.img'}
                        $name='image-{0:00}{1}' -f $number,$ext
                        Download-File $image (Join-Path $folder $name)
                        $body=$body.Replace($image,$name)
                        $entry.files+=($relative+'/'+$name)
                    } catch {$entry.errors+=('Image '+$number+': '+$_.Exception.Message);$entry.status='partial'}
                }
                $html='<!doctype html><html lang="ko"><head><meta charset="utf-8"><title>'+[Net.WebUtility]::HtmlEncode($unit.title)+'</title></head><body><h1>'+[Net.WebUtility]::HtmlEncode($unit.title)+'</h1>'+$body+'</body></html>'
                [IO.File]::WriteAllText((Join-Path $folder 'body.html'),$html,$utf8)
                $plain=[regex]::Replace($body,'(?i)<br\s*/?>|</p>|</li>|</h[1-6]>|</div>',"`n")
                $plain=[Net.WebUtility]::HtmlDecode([regex]::Replace($plain,'<[^>]+>',''))
                [IO.File]::WriteAllText((Join-Path $folder 'body.txt'),$plain,$utf8)
                [IO.File]::WriteAllText((Join-Path $folder 'links.json'),(ConvertTo-Json -InputObject $links),$utf8)
                $entry.files+=@($relative+'/body.html';$relative+'/body.txt';$relative+'/links.json')
            } catch {$entry.status='partial';$entry.errors+=('Body: '+$_.Exception.Message)}
        }
        if ($unit.hasAttachment) {
            try {
                $attachment=Api-Json ('/client/api/v1/units/attachment?unitId='+$unit.id)
                $name=([string]$attachment.name -replace '[<>:"/\\|?*\x00-\x1f]','_').TrimEnd('.',' ')
                if (!$name) {$name='attachment'+[IO.Path]::GetExtension(([uri]$attachment.url).AbsolutePath)}
                if ($name.Length -gt 120) {$name=$name.Substring(0,100)+[IO.Path]::GetExtension($name)}
                Download-File $attachment.url (Join-Path $folder $name)
                $entry.files+=($relative+'/'+$name)
            } catch {$entry.status='partial';$entry.errors+=('Attachment: '+$_.Exception.Message)}
        }
        $entries.Add($entry)
        [IO.File]::WriteAllText((Join-Path $materialRoot 'manifest.json'),(ConvertTo-Json -InputObject @($entries.ToArray()) -Depth 15),$utf8)
        Write-Output ('Material unit {0}: {1}, files={2}' -f $unit.id,$entry.status,$entry.files.Count)
        Start-Sleep -Milliseconds 250
    }
}
$rows=@('| Unit | Title | Status | Files |','| --- | --- | --- | --- |')
foreach ($entry in $entries) {
    $links=($entry.files | ForEach-Object {'['+[IO.Path]::GetFileName($_)+']('+[uri]::EscapeUriString($_)+')'}) -join ', '
    $rows+='| {0} | {1} | {2} | {3} |' -f $entry.unit_id,($entry.title -replace '\|','\|'),$entry.status,$links
}
[IO.File]::WriteAllText((Join-Path $materialRoot 'README.md'),($rows -join "`n"),$utf8)
Write-Output ('RESULT: {0} material units, {1} incomplete' -f $entries.Count,@($entries | Where-Object {$_.status -ne 'downloaded'}).Count)

