$ErrorActionPreference = 'Stop'
$target = 'C:\Users\djliz\cpng\docs\boards'
New-Item -ItemType Directory -Force -Path $target | Out-Null
$lock = $null
try {
    $lock = [System.IO.File]::Open((Join-Path $target '.sync.lock'), 'OpenOrCreate', 'ReadWrite', 'None')
    $since = '0'
    $watermark = Join-Path $target 'export-watermark.json'
    if (Test-Path -LiteralPath $watermark) {
        $since = ([double](Get-Content -Raw -LiteralPath $watermark | ConvertFrom-Json).server_epoch).ToString('R', [Globalization.CultureInfo]::InvariantCulture)
    }
    $archive = Join-Path $env:TEMP ('wing-sync-' + [Guid]::NewGuid().ToString('N') + '.tar.gz')
    $info = New-Object System.Diagnostics.ProcessStartInfo
    $info.FileName = 'ssh.exe'
    $info.Arguments = '-o BatchMode=yes -o ConnectTimeout=15 aws103 /home/ec2-user/cpng-wing-notices/.venv/bin/python /home/ec2-user/cpng-wing-notices/export.py --since ' + $since
    $info.UseShellExecute = $false
    $info.CreateNoWindow = $true
    $info.RedirectStandardOutput = $true
    $process = [System.Diagnostics.Process]::Start($info)
    $stream = [IO.File]::Create($archive)
    try { $process.StandardOutput.BaseStream.CopyTo($stream) } finally { $stream.Dispose() }
    $process.WaitForExit()
    if ($process.ExitCode -ne 0) { throw 'AWS archive export failed' }
    & tar.exe -xzf $archive -C $target
    if ($LASTEXITCODE -ne 0) { throw 'Archive extraction failed' }
    Remove-Item -LiteralPath $archive
    @{last_sync_utc=[DateTime]::UtcNow.ToString('o'); status='ok'} | ConvertTo-Json | Set-Content -Encoding UTF8 (Join-Path $target 'sync-status.json')
} catch {
    if ($lock) {
        @{last_attempt_utc=[DateTime]::UtcNow.ToString('o'); status='error'; message='AWS sync failed; see Windows task result and rerun sync.ps1.'} | ConvertTo-Json | Set-Content -Encoding UTF8 (Join-Path $target 'sync-status.json')
    }
    throw
} finally {
    if ($lock) { $lock.Dispose() }
}
