command:
$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath('cpng\docs\api')
$records=Get-Content (Join-Path $root 'manifest.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$issues=@();$count=0
foreach ($r in $records) {
 $path=Join-Path $root $r.html
 if (!(Test-Path -LiteralPath $path)) {$issues+='Missing '+$r.html;continue}
 $hash=(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash
 if ($hash -ne $r.sha256) {$issues+='Hash '+$r.html}
 if (!(Test-Path -LiteralPath (Join-Path $root $r.markdown))) {$issues+='Missing '+$r.markdown}
 $count++
}
Write-Output ('Checked documents='+$count+', issues='+$issues.Count)
$issues | Select-Object -First 5
$assets=Get-Content (Join-Path $root 'assets.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$assetOk=0
foreach ($a in $assets) {if ($a.file) {if ((Get-FileHash -LiteralPath (Join-Path $root $a.file) -Algorithm SHA256).Hash -ne $a.sha256) {throw 'Asset hash mismatch'};$assetOk++}}
Write-Output ('Verified assets='+$assetOk)

