command:
$processes=Get-CimInstance Win32_Process | Where-Object {$_.ProcessId -in @(12720,21940,18144,21584)}
foreach ($process in $processes) {
 if (($process.Name -eq 'python.exe' -and $process.CommandLine -match 'python.exe.* -$') -or ($process.Name -eq 'powershell.exe' -and ($process.CommandLine.Contains('faulthandler.dump_traceback_later') -or $process.CommandLine.Contains('Checked documents=')))) { Stop-Process -Id $process.ProcessId -ErrorAction SilentlyContinue }
}
Write-Output 'Stopped delayed verification processes.'

